def split_words(sentence: str) -> list[str]:
    """Splits a sentence into a list of words."""
    return sentence.split()

def reverse_list_in_place(word_list: list[str]) -> None:
    """Reverses the order of elements in a list in-place."""
    word_list.reverse()

def join_words(word_list: list[str]) -> str:
    """Joins a list of words into a single string, separated by spaces."""
    return ' '.join(word_list)

def reverse_sentence_words(sentence: str) -> str:
    """
    Reverses the order of words in a given sentence.

    Args:
        sentence: The input string representing a sentence.

    Returns:
        A new string with the order of words reversed.
    """
    words = split_words(sentence)
    reverse_list_in_place(words)
    reversed_sentence = join_words(words)
    return reversed_sentence

def example_one():
    """Demonstrates the function with 'hello world'."""
    print(reverse_sentence_words('hello world'))

def example_two():
    """Demonstrates the function with 'python is fun'."""
    print(reverse_sentence_words('python is fun'))

if __name__ == '__main__':
    example_one()
    example_two()

