def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    """
    Calculates the total amount after compound interest.

    Args:
        principal (float): The initial amount of money.
        rate (float): The annual interest rate (as a decimal).
        compounding_frequency (int): The number of times interest is compounded per year.
        time_years (int): The number of years the money is invested or borrowed for.

    Returns:
        float: The total amount after compound interest.
    """
    total_amount = principal * (1 + rate / compounding_frequency)**(compounding_frequency * time_years)
    return total_amount

def get_principal_input():
    """
    Prompts the user to enter the principal amount and validates it.

    Returns:
        float: The validated principal amount.
    """
    while True:
        try:
            principal = float(input("Enter the principal amount: "))
            if principal >= 0:
                return principal
            else:
                print("Principal cannot be negative. Please try again.")
        except ValueError:
            print("Invalid input. Please enter a number.")

def get_rate_input():
    """
    Prompts the user to enter the annual interest rate and validates it.

    Returns:
        float: The validated annual interest rate (as a decimal).
    """
    while True:
        try:
            rate = float(input("Enter the annual interest rate (as a decimal, e.g., 0.05 for 5%): "))
            if 0 <= rate <= 1:
                return rate
            else:
                print("Rate must be between 0 and 1. Please try again.")
        except ValueError:
            print("Invalid input. Please enter a number.")

def get_compounding_frequency_input():
    """
    Prompts the user to enter the compounding frequency and validates it.

    Returns:
        int: The validated compounding frequency.
    """
    while True:
        try:
            frequency = int(input("Enter the number of times interest is compounded per year: "))
            if frequency > 0:
                return frequency
            else:
                print("Compounding frequency must be positive. Please try again.")
        except ValueError:
            print("Invalid input. Please enter an integer.")

def get_time_years_input():
    """
    Prompts the user to enter the time period in years and validates it.

    Returns:
        int: The validated time period in years.
    """
    while True:
        try:
            time = int(input("Enter the time period in years: "))
            if time >= 0:
                return time
            else:
                print("Time cannot be negative. Please try again.")
        except ValueError:
            print("Invalid input. Please enter an integer.")

if __name__ == "__main__":
    """
    Main execution block for the compound interest calculator.
    It gathers user input and displays the calculated total amount.
    """
    principal = get_principal_input()
    rate = get_rate_input()
    compounding_frequency = get_compounding_frequency_input()
    time_years = get_time_years_input()

    final_amount = calculate_compound_interest(principal, rate, compounding_frequency, time_years)
    print(f"The total amount after {time_years} years will be: {final_amount:.2f}")

