def _char_to_ascii(char):
    """Converts a single character to its ASCII integer value."""
    return ord(char)

def _ascii_to_char(ascii_val):
    """Converts an ASCII integer value back to its character representation."""
    return chr(ascii_val)

def _xor_chars_ascii(char1, char2):
    """XORs the ASCII values of two characters and returns the result."""
    return _char_to_ascii(char1) ^ _char_to_ascii(char2)

def _process_character(char, key_char):
    """Applies the XOR operation to a single character with the key character."""
    xor_result = _xor_chars_ascii(char, key_char)
    return _ascii_to_char(xor_result)

def xor_cipher(text, key_char):
    """
    Encrypts or decrypts a string using a XOR cipher with a single character key.

    Args:
        text (str): The input string to be encrypted or decrypted.
        key_char (str): A single character used as the key for the XOR operation.

    Returns:
        str: The resulting string after applying the XOR cipher.
    """
    if not isinstance(key_char, str) or len(key_char) != 1:
        raise ValueError("key_char must be a single character string.")

    result_chars = [_process_character(char, key_char) for char in text]
    return "".join(result_chars)

def _verify_decryption(original_text, key):
    """
    Helper function to verify that double encryption with the same key
    returns the original text.
    """
    encrypted_text = xor_cipher(original_text, key)
    decrypted_text = xor_cipher(encrypted_text, key)
    return decrypted_text == original_text

