def _celsius_to_fahrenheit(celsius):
    """
    Converts a temperature from Celsius to Fahrenheit.
    """
    return (celsius * 9/5) + 32

def _fahrenheit_to_celsius(fahrenheit):
    """
    Converts a temperature from Fahrenheit to Celsius.
    """
    return (fahrenheit - 32) * 5/9

def _celsius_to_kelvin(celsius):
    """
    Converts a temperature from Celsius to Kelvin.
    """
    return celsius + 273.15

def _kelvin_to_celsius(kelvin):
    """
    Converts a temperature from Kelvin to Celsius.
    """
    return kelvin - 273.15

def convert_temperature(value, unit_from, unit_to):
    """
    Converts a temperature from one unit to another.

    Args:
        value (float): The temperature value to convert.
        unit_from (str): The unit of the input temperature ('C', 'F', or 'K').
        unit_to (str): The desired unit for the output temperature ('C', 'F', or 'K').

    Returns:
        float: The converted temperature value.
    """
    if unit_from == unit_to:
        return float(value)

    if unit_from == 'C':
        if unit_to == 'F':
            return _celsius_to_fahrenheit(value)
        elif unit_to == 'K':
            return _celsius_to_kelvin(value)
    elif unit_from == 'F':
        celsius_val = _fahrenheit_to_celsius(value)
        if unit_to == 'C':
            return celsius_val
        elif unit_to == 'K':
            return _celsius_to_kelvin(celsius_val)
    elif unit_from == 'K':
        celsius_val = _kelvin_to_celsius(value)
        if unit_to == 'C':
            return celsius_val
        elif unit_to == 'F':
            return _celsius_to_fahrenheit(celsius_val)

    return float(value) # Should not be reached with valid inputs.

